// Types for the 5e rules data (2024 rules, SRD 5.2.1), and the rule calculations
// for characters. The data itself is generated by scripts/build-rules.mjs into
// client/src/rules/srd-2024.json.

export type Ability = 'str' | 'dex' | 'con' | 'int' | 'wis' | 'cha';
export const ABILITIES: Ability[] = ['str', 'dex', 'con', 'int', 'wis', 'cha'];
export const ABILITY_NAMES: Record<Ability, string> = {
  str: 'Strength',
  dex: 'Dexterity',
  con: 'Constitution',
  int: 'Intelligence',
  wis: 'Wisdom',
  cha: 'Charisma',
};

export interface ItemRef {
  index: string | null; // null when it's "any X of your choice"
  name: string;
  qty: number;
}
/** One "pick A or B" equipment choice: each option is a set of items plus gold. */
export interface EquipmentOption {
  label: string; // "A", "B", ...
  items: ItemRef[];
  gold: number;
}

export interface ClassLevel {
  level: number;
  profBonus: number;
  features: string[]; // feature indexes
  cantrips?: number;
  prepared?: number;
  slots?: number[]; // spell slots for spell levels 1..9
}

export interface RulesClass {
  index: string;
  name: string;
  hitDie: number;
  primary: Ability[];
  saves: Ability[];
  skillChoice: { choose: number; from: string[] }; // skill indexes
  proficiencies: string[]; // armour/weapon proficiencies, by name
  equipment: EquipmentOption[];
  spellcasting: Ability | null;
  subclasses: { index: string; name: string }[];
  levels: ClassLevel[];
}

export interface RulesSpecies {
  index: string;
  name: string;
  size: string;
  speed: number;
  traits: string[];
  subspecies: { index: string; name: string; traits: string[] }[];
}

export interface RulesBackground {
  index: string;
  name: string;
  abilities: Ability[]; // the three abilities it can increase
  feat: { index: string; name: string; note?: string };
  skills: string[];
  tools: string[];
  equipment: EquipmentOption[];
}

export interface RulesItem {
  index: string;
  name: string;
  kind: 'weapon' | 'armor' | 'shield' | 'gear' | 'tool' | 'pack' | 'other';
  armor?: { base: number; dex: boolean; maxDex?: number; category: 'light' | 'medium' | 'heavy' };
  weapon?: { damage: string; type: string; properties: string[]; range?: { normal: number; long?: number }; ranged: boolean };
  contents?: ItemRef[];
  cost?: string;
  weight?: number;
}

export interface RulesSpell {
  index: string;
  name: string;
  level: number;
  school: string;
  classes: string[];
  castingTime: string;
  range: string;
  components: string;
  duration: string;
  concentration: boolean;
  ritual: boolean;
  description: string;
  rangeFt: number | null; // 0 = self, 5 = touch, null = special
  area?: { shape: AreaShape; size: number; width?: number };
  attack?: 'melee' | 'ranged';
}

export type AreaShape = 'sphere' | 'cone' | 'cube' | 'cylinder' | 'emanation' | 'line';

export interface RulesText {
  index: string;
  name: string;
  description: string;
}

export interface RulesData {
  source: string;
  skills: { index: string; name: string; ability: Ability }[];
  classes: RulesClass[];
  species: RulesSpecies[];
  backgrounds: RulesBackground[];
  feats: RulesText[];
  traits: RulesText[];
  features: (RulesText & { class: string; level: number })[];
  spells: RulesSpell[];
  items: RulesItem[];
  languages: string[];
  alignments: string[];
}

// ---------------------------------------------------------------------------
// Characters
// ---------------------------------------------------------------------------

export interface CharacterItem {
  index: string | null; // rules item, or null for something custom
  name: string;
  qty: number;
  equipped?: boolean;
}

export interface Character {
  id: string;
  ownerId: string | null; // the player (device) who plays it; null = nobody (e.g. a DM-made character)
  name: string;
  level: number;
  classIndex: string;
  subclassIndex: string | null;
  speciesIndex: string;
  subspeciesIndex: string | null;
  backgroundIndex: string;
  alignment: string;
  abilities: Record<Ability, number>; // final scores, bonuses included
  abilityMethod: 'roll' | 'array' | 'pointbuy' | 'manual';
  skills: string[]; // proficient skill indexes
  languages: string[];
  feats: string[];
  items: CharacterItem[];
  gold: number;
  cantrips: string[]; // spell indexes
  spells: string[]; // prepared spell indexes (level 1+)
  hp: { max: number; current: number; temp: number };
  spellSlotsUsed: number[]; // per spell level 1..9
  /** Numbers the player set by hand instead of the calculated ones. */
  overrides: { ac?: number; speed?: number };
  details: { appearance: string; personality: string; ideals: string; bonds: string; flaws: string; backstory: string };
  /** Calculated when saved, so the server and other screens don't need the rules data. */
  summary: { ac: number; speedFt: number; initiative: number; passivePerception: number; classLine: string };
  createdWith: 'builder' | 'manual';
  updatedAt: number;
}

export const STANDARD_ARRAY = [15, 14, 13, 12, 10, 8];
export const POINT_BUY_BUDGET = 27;
export const POINT_BUY_COST: Record<number, number> = { 8: 0, 9: 1, 10: 2, 11: 3, 12: 4, 13: 5, 14: 7, 15: 9 };

export const mod = (score: number) => Math.floor((score - 10) / 2);
export const signed = (n: number) => (n >= 0 ? `+${n}` : `${n}`);
export const profBonus = (level: number) => 2 + Math.floor((Math.max(1, level) - 1) / 4);

/** Everything on a character sheet that follows from the rules. */
export function derive(c: Character, rules: RulesData) {
  const cls = rules.classes.find((x) => x.index === c.classIndex);
  const species = rules.species.find((x) => x.index === c.speciesIndex);
  const prof = profBonus(c.level);
  const mods = Object.fromEntries(Object.entries(c.abilities).map(([k, v]) => [k, mod(v)])) as Record<Ability, number>;

  const saves = Object.fromEntries(
    Object.keys(c.abilities).map((a) => [a, mods[a as Ability] + (cls?.saves.includes(a as Ability) ? prof : 0)]),
  ) as Record<Ability, number>;
  const skills = rules.skills.map((s) => ({
    ...s,
    proficient: c.skills.includes(s.index),
    bonus: mods[s.ability] + (c.skills.includes(s.index) ? prof : 0),
  }));

  // Armour Class: worn armour (+ Dex, capped for medium), shield, or Unarmored Defense.
  const equipped = c.items.filter((i) => i.equipped && i.index).map((i) => rules.items.find((r) => r.index === i.index)!).filter(Boolean);
  const armor = equipped.find((i) => i.kind === 'armor' && i.armor);
  const shield = equipped.some((i) => i.kind === 'shield');
  let ac: number;
  if (armor?.armor) {
    const dex = armor.armor.dex ? Math.min(mods.dex, armor.armor.maxDex ?? Infinity) : 0;
    ac = armor.armor.base + dex;
  } else if (c.classIndex === 'barbarian') ac = 10 + mods.dex + mods.con;
  else if (c.classIndex === 'monk' && !shield) ac = 10 + mods.dex + mods.wis;
  else ac = 10 + mods.dex;
  if (shield) ac += 2;
  ac = c.overrides.ac ?? ac;

  const speedFt = c.overrides.speed ?? species?.speed ?? 30;
  const initiative = mods.dex + (c.feats.includes('alert') ? prof : 0);
  const perception = skills.find((s) => s.index === 'perception');
  const passivePerception = 10 + (perception?.bonus ?? mods.wis);

  const levelRow = cls?.levels.find((l) => l.level === c.level);
  const spellAbility = cls?.spellcasting ?? null;
  const spellcasting = spellAbility
    ? {
        ability: spellAbility,
        saveDc: 8 + prof + mods[spellAbility],
        attack: prof + mods[spellAbility],
        slots: levelRow?.slots ?? [],
        cantrips: levelRow?.cantrips ?? 0,
        prepared: levelRow?.prepared ?? 0,
      }
    : null;

  const attacks = c.items
    .map((i) => ({ item: i, rules: i.index ? rules.items.find((r) => r.index === i.index) : undefined }))
    .filter((x) => x.rules?.weapon)
    .map(({ item, rules: r }) => {
      const w = r!.weapon!;
      const finesse = w.properties.includes('Finesse');
      const ability: Ability = w.ranged ? 'dex' : finesse && mods.dex > mods.str ? 'dex' : 'str';
      return {
        name: item.name,
        toHit: mods[ability] + prof, // all classes in the SRD are proficient with Simple weapons; good enough for a sheet
        damage: `${w.damage}${mods[ability] ? signed(mods[ability]) : ''} ${w.type.toLowerCase()}`,
        range: w.range ? (w.range.long ? `${w.range.normal}/${w.range.long} ft` : `${w.range.normal} ft`) : 'reach 5 ft',
      };
    });

  const classLine = [cls?.name ?? c.classIndex, c.level, '·', species?.name ?? c.speciesIndex].join(' ');
  return { cls, species, prof, mods, saves, skills, ac, speedFt, initiative, passivePerception, spellcasting, attacks, classLine };
}

/** Average hit points for a level (level 1: full hit die; later levels: average roll). */
export function averageHp(hitDie: number, level: number, conMod: number) {
  const perLevel = Math.floor(hitDie / 2) + 1;
  return Math.max(1, hitDie + conMod + (level - 1) * Math.max(1, perLevel + conMod));
}

/** Highest possible hit points for a level, to warn about numbers that can't be right. */
export function maxPossibleHp(hitDie: number, level: number, conMod: number) {
  return Math.max(1, hitDie + conMod + (level - 1) * Math.max(1, hitDie + conMod));
}

export function emptyCharacter(id = ''): Character {
  return {
    id,
    ownerId: null,
    name: '',
    level: 1,
    classIndex: '',
    subclassIndex: null,
    speciesIndex: '',
    subspeciesIndex: null,
    backgroundIndex: '',
    alignment: '',
    abilities: { str: 10, dex: 10, con: 10, int: 10, wis: 10, cha: 10 },
    abilityMethod: 'array',
    skills: [],
    languages: ['Common'],
    feats: [],
    items: [],
    gold: 0,
    cantrips: [],
    spells: [],
    hp: { max: 1, current: 1, temp: 0 },
    spellSlotsUsed: [0, 0, 0, 0, 0, 0, 0, 0, 0],
    overrides: {},
    details: { appearance: '', personality: '', ideals: '', bonds: '', flaws: '', backstory: '' },
    summary: { ac: 10, speedFt: 30, initiative: 0, passivePerception: 10, classLine: '' },
    createdWith: 'builder',
    updatedAt: 0,
  };
}

/** Fills in the calculated summary before saving. */
export function withSummary(c: Character, rules: RulesData): Character {
  const d = derive(c, rules);
  return {
    ...c,
    summary: { ac: d.ac, speedFt: d.speedFt, initiative: d.initiative, passivePerception: d.passivePerception, classLine: d.classLine },
  };
}
